{"hypotheses": [
{"name": "Composite 1", "mechanism": "Firms with high advertising expenses and low book leverage tend to outperform, as they can capitalize on their market presence and manage their debt effectively.", "expression": {"terms": [{"weight": 1.0, "primitive": "AdExp"}, {"weight": -1.0, "primitive": "BookLeverage"}], "regime": "VIX_BELOW_TRAILING_MEDIAN", "vol_target": true}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "VIX_BELOW_TRAILING_MEDIAN", "direction": "higher"}, {"type": "size_segment", "segment": "small", "direction": "stronger"}, {"type": "correlation", "primitive": "Mom6m", "bound": "below", "threshold": 0.3}], "expected_annualized_sharpe": 0.8, "expected_decay_half_life_months": 24},
