{"name": "Composite 7", "mechanism": "Firms with high R&D ability and low idiosyncratic volatility tend to outperform, as they can capitalize on their innovative products and manage their risk effectively.", "expression": {"terms": [{"weight": 1.0, "primitive": "RDAbility"}, {"weight": -1.0, "primitive": "IdioVolAHT"}], "regime": "TERM_SPREAD_NEGATIVE", "vol_target": true}, "auxiliary_predictions": [{"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"}, {"type": "size_segment", "segment": "micro", "direction": "stronger"}, {"type": "correlation", "primitive": "Mom6mJunk", "bound": "below", "threshold": 0.3}], "expected_annualized_sharpe": 0.6, "expected_decay_half_life_months": 12},
